const ShoppingCart = (function() {
  // 1. Private variables (cannot be accessed outside)
  const cart = [];

  function calculateTax(amount) { return amount * 0.1; }

  // 2. The Public API (What gets returned)
  return {
    addItem: function(item) {
      cart.push(item);
      console.log(`${item.name} added.`);
    },
    getCartCount: function() {
      return cart.length;
    }
  };
})(); // IIFE runs instantly

ShoppingCart.addItem({ name: 'Apple', price: 1 });
console.log(ShoppingCart.getCartCount()); // 1

// Completely hidden and protected!
console.log(ShoppingCart.cart); // undefined
